   12	// Page is one page of results.
   13	type Page[T any] struct {
   14		Items      []T
   15		Number     int  // 1-based page number requested
   16		TotalPages int  // number of non-empty pages (0 for an empty input)
   17		HasNext    bool // true if a later page has items
   18		HasPrev    bool // true if Number > 1
   19	}
   20	
   21	// Get returns page number n (1-based) of items, with size items per page.
   22	// Pages past the end are returned with no Items (HasPrev still reflects n).
   23	// The returned Items slice must not alias the input (callers may modify it).
   24	func Get[T any](items []T, size, n int) (Page[T], error) {
   25		if size < 1 {
   26			return Page[T]{}, ErrBadSize
   27		}
   28		if n < 1 {
   29			return Page[T]{}, ErrBadPage
   30		}
   31		total := len(items)/size + 1
   32		if len(items) == 0 {
   33			total = 0
   34		}
   35		start := (n - 1) * size
   36		end := start + size
   37		if end > len(items) {
   38			end = len(items) - 1
   39		}
   40		p := Page[T]{
   41			Items:      items[start:end],
   42			Number:     n,
   43			TotalPages: total,
   44			HasNext:    n < total,
   45			HasPrev:    n > 1,
   46		}
   47		return p, nil
   48	}
