   50	// All splits items into consecutive pages.
   51	func All[T any](items []T, size int) ([][]T, error) {
   52		if size < 1 {
   53			return nil, ErrBadSize
   54		}
   55		var out [][]T
   56		for i := 0; i < len(items); i += size {
   57			end := i + size
   58			if end > len(items) {
   59				end = len(items)
   60			}
   61			out = append(out, items[i:end])
   62		}
   63		return out, nil
